<div class="row g-4"><div class="col-lg-7"><?php panel_start('Profil akun'); ?><form @submit.prevent="state['profile'+role]=accountName; persist(); notify('Profil contoh tersimpan di browser.');"><div class="d-flex align-items-center gap-3 mb-4"><div class="user-avatar large"><?= $role === 'pendaftar' ? 'YK' : 'O1' ?></div><div><strong><?= $role === 'pendaftar' ? 'Yohanes Kristian' : 'Operator 1' ?></strong><small class="d-block text-muted"><?= e($roleNames[$role]) ?> · Akun contoh</small></div></div><div class="mb-3"><label for="account-name" class="form-label">Nama tampilan</label><input id="account-name" class="form-control" x-model="accountName" required></div><div class="mb-3"><label for="account-email" class="form-label">Email terhubung</label><input id="account-email" type="email" class="form-control" value="<?= $role === 'pendaftar' ? 'yohanes.contoh' : 'operator1' ?>@example.com" readonly></div><div class="notice-box info"><i class="bi bi-google"></i><div><strong>Jalur Google (simulasi)</strong><p>Pengaitan akun Google dengan akun lokal memerlukan verifikasi kepemilikan. Pratinjau ini tidak terhubung ke Google.</p></div></div><button class="btn btn-purple">Simpan profil contoh</button></form><?php panel_end(); ?></div><div class="col-lg-5"><?php panel_start('Keamanan akun'); ?><form @submit.prevent="if(password !== confirmPassword) { notify('Konfirmasi kata sandi belum cocok.'); } else { password=''; confirmPassword=''; notify('Simulasi penggantian sandi berhasil. Sandi tidak disimpan.'); }"><div class="mb-3"><label class="form-label" for="new-pass">Kata sandi baru</label><input id="new-pass" type="password" class="form-control" x-model="password" minlength="8" required autocomplete="new-password"></div><div class="mb-4"><label class="form-label" for="confirm-pass">Ulangi kata sandi baru</label><input id="confirm-pass" type="password" class="form-control" x-model="confirmPassword" minlength="8" required autocomplete="new-password"></div><button class="btn btn-outline-purple w-100">Simulasikan ganti sandi</button></form><?php panel_end(); ?></div></div>
